FUNCTION compute_qk
1217: template <typename KTraits, bool REPACK_BF16 = false>
1218: __device__ __forceinline__ void compute_qk(
1219:     smem_t<KTraits::SWIZZLE_MODE_Q>* q_smem, uint32_t* q_smem_offset_r,
1220:     smem_t<KTraits::SWIZZLE_MODE_KV>* k_smem, uint32_t* k_smem_offset_r, uint8_t* k_sf_smem,
1221:     uint32_t lane_idx, typename KTraits::DTypeQKAccum (*s_frag)[KTraits::NUM_MMA_KV][8]) {
1222:   constexpr uint32_t UPCAST_STRIDE_Q = KTraits::UPCAST_STRIDE_Q;
1223:   constexpr uint32_t UPCAST_STRIDE_K = KTraits::UPCAST_STRIDE_K;
1224:   // When reading from the BF16 repack buffer, K is laid out as native 16-bit, so
1225:   // use the 16-bit b128 stride / element size instead of the FP8 packed ones.
1226:   constexpr uint32_t KV_STRIDE = REPACK_BF16 ? KTraits::REPACK_STRIDE_QK : UPCAST_STRIDE_K;
1227:   constexpr uint32_t KV_ESIZE =
1228:       REPACK_BF16 ? sizeof(typename KTraits::DTypeQ) : sizeof(typename KTraits::DTypeKV);
1229:   uint32_t a_frag[KTraits::NUM_MMA_Q][4], b_frag[4];
1230:   // compute q*k^T
1231: #pragma unroll
1232:   for (uint32_t mma_d = 0; mma_d < KTraits::NUM_MMA_D_QK; ++mma_d) {
1233: #pragma unroll
1234:     for (uint32_t mma_q = 0; mma_q < KTraits::NUM_MMA_Q; ++mma_q) {
1235:       q_smem->ldmatrix_m8n8x4(*q_smem_offset_r, a_frag[mma_q]);
1236:       *q_smem_offset_r =
1237:           q_smem->template advance_offset_by_row<16, UPCAST_STRIDE_Q>(*q_smem_offset_r);
1238:     }
1239: 
1240:     *q_smem_offset_r = q_smem->template advance_offset_by_column<2>(*q_smem_offset_r, mma_d) -
1241:                        KTraits::NUM_MMA_Q * 16 * UPCAST_STRIDE_Q;
1242: 
1243: #pragma unroll
1244:     for (uint32_t mma_kv = 0; mma_kv < KTraits::NUM_MMA_KV; ++mma_kv) {
1245:       if constexpr (sizeof(typename KTraits::DTypeKV) == 1 && !REPACK_BF16) {
1246:         uint32_t b_frag_quant[2];
1247:         if (mma_d % 2 == 0) {
1248:           k_smem->ldmatrix_m8n8x4_left_half(*k_smem_offset_r, b_frag_quant);
1249:         } else {
1250:           k_smem->ldmatrix_m8n8x4_right_half(*k_smem_offset_r, b_frag_quant);
1251:         }
1252:         if constexpr (is_fp4_type_v<typename KTraits::DTypeKV>) {
1253:           b_frag_quant[0] = frag_layout_swizzle_16b_to_4b(b_frag_quant[0]);
1254:           b_frag_quant[1] = frag_layout_swizzle_16b_to_4b(b_frag_quant[1]);
1255:         } else {
1256:           b_frag_quant[0] = frag_layout_swizzle_16b_to_8b(b_frag_quant[0]);
1257:           b_frag_quant[1] = frag_layout_swizzle_16b_to_8b(b_frag_quant[1]);
1258:         }
1259:         vec_cast<typename KTraits::DTypeQ, typename KTraits::DTypeKV>::cast<8>(
1260:             (typename KTraits::DTypeQ*)b_frag, (typename KTraits::DTypeKV*)b_frag_quant);
1261:         if constexpr (is_fp4_type_v<typename KTraits::DTypeKV>) {
1262:           // Apply scaling factors for K.
1263:           // SF smem is linear: sf[kv_row * SF_COLS + hd_group], SF_COLS = HEAD_DIM_QK/16.
1264:           // For m16n8k16 B layout, thread t's KV rows are t/4 and t/4+8 in the mma_kv tile.
1265:           // b_frag[0,1] share KV row (t/4), b_frag[2,3] share KV row (t/4+8).
1266:           using DTypeQ_ = typename KTraits::DTypeQ;
1267:           using packed2_ = std::conditional_t<std::is_same_v<DTypeQ_, half>, half2, __nv_bfloat162>;
1268:           constexpr uint32_t SF_COLS_K = KTraits::NUM_MMA_D_QK;  // HEAD_DIM_QK / 16
1269:           uint32_t sf_base = (mma_kv * 16 + lane_idx / 4) * SF_COLS_K + mma_d;
1270:           __nv_fp8_e4m3 sf_a_fp8, sf_b_fp8;
1271:           sf_a_fp8.__x = k_sf_smem[sf_base];
1272:           sf_b_fp8.__x = k_sf_smem[sf_base + 8 * SF_COLS_K];
1273:           packed2_ scale_a{static_cast<DTypeQ_>(sf_a_fp8), static_cast<DTypeQ_>(sf_a_fp8)};
1274:           packed2_ scale_b{static_cast<DTypeQ_>(sf_b_fp8), static_cast<DTypeQ_>(sf_b_fp8)};
1275:           *(packed2_*)&b_frag[0] = __hmul2(*(packed2_*)&b_frag[0], scale_a);
1276:           *(packed2_*)&b_frag[1] = __hmul2(*(packed2_*)&b_frag[1], scale_a);
1277:           *(packed2_*)&b_frag[2] = __hmul2(*(packed2_*)&b_frag[2], scale_b);
1278:           *(packed2_*)&b_frag[3] = __hmul2(*(packed2_*)&b_frag[3], scale_b);
1279:         }
1280:       } else {
1281:         k_smem->ldmatrix_m8n8x4(*k_smem_offset_r, b_frag);
1282:       }
1283:       *k_smem_offset_r = k_smem->template advance_offset_by_row<16, KV_STRIDE>(*k_smem_offset_r);
1284: 
1285: #pragma unroll
1286:       for (uint32_t mma_q = 0; mma_q < KTraits::NUM_MMA_Q; ++mma_q) {
1287:         if constexpr (std::is_same_v<typename KTraits::DTypeQKAccum, float>) {
1288:           if (mma_d == 0) {
1289:             mma::mma_sync_m16n16k16_row_col_f16f16f32<typename KTraits::DTypeQ, MMAMode::kInit>(
1290:                 s_frag[mma_q][mma_kv], a_frag[mma_q], b_frag);
1291:           } else {
1292:             mma::mma_sync_m16n16k16_row_col_f16f16f32<typename KTraits::DTypeQ>(
1293:                 s_frag[mma_q][mma_kv], a_frag[mma_q], b_frag);
1294:           }
1295:         } else if (std::is_same_v<typename KTraits::DTypeQKAccum, half>) {
1296:           if (mma_d == 0) {
1297:             mma::mma_sync_m16n16k16_row_col_f16f16f16<MMAMode::kInit>(
1298:                 (uint32_t*)s_frag[mma_q][mma_kv], a_frag[mma_q], b_frag);
1299:           } else {
1300:             mma::mma_sync_m16n16k16_row_col_f16f16f16((uint32_t*)s_frag[mma_q][mma_kv],
1301:                                                       a_frag[mma_q], b_frag);
1302:           }
1303:         }
1304:       }
1305:     }
1306:     if constexpr (sizeof(typename KTraits::DTypeKV) == 1 && !REPACK_BF16) {
1307:       if (mma_d % 2 == 1) {
1308:         *k_smem_offset_r =
1309:             k_smem->template advance_offset_by_column<2>(*k_smem_offset_r, mma_d / 2);
1310:       }
1311:       *k_smem_offset_r -= KTraits::NUM_MMA_KV * 16 * KV_STRIDE;
1312:     } else {
1313:       *k_smem_offset_r = k_smem->template advance_offset_by_column<2>(*k_smem_offset_r, mma_d) -
1314:                          KTraits::NUM_MMA_KV * 16 * KV_STRIDE;
1315:     }
1316:   }
1317:   *q_smem_offset_r -= KTraits::NUM_MMA_D_QK * 2;
1318:   *k_smem_offset_r -= KTraits::NUM_MMA_D_QK * KV_ESIZE;
1319: }

FUNCTION compute_sfm_v
1727: template <typename KTraits, bool REPACK_BF16 = false>
1728: __device__ __forceinline__ void compute_sfm_v(
1729:     smem_t<KTraits::SWIZZLE_MODE_KV>* v_smem, uint32_t* v_smem_offset_r, uint8_t* v_sf_smem,
1730:     uint32_t lane_idx, typename KTraits::DTypeQKAccum (*s_frag)[KTraits::NUM_MMA_KV][8],
1731:     float (*o_frag)[KTraits::NUM_MMA_D_VO_TILE][8], float (*d)[2], const uint32_t d_base = 0) {
1732:   constexpr uint32_t UPCAST_STRIDE_V = KTraits::UPCAST_STRIDE_V;
1733:   // When reading from the BF16 repack buffer, V is native 16-bit.
1734:   constexpr uint32_t VV_STRIDE = REPACK_BF16 ? KTraits::REPACK_STRIDE_VO : UPCAST_STRIDE_V;
1735:   constexpr uint32_t VV_ESIZE =
1736:       REPACK_BF16 ? sizeof(typename KTraits::DTypeQ) : sizeof(typename KTraits::DTypeKV);
1737: 
1738:   typename KTraits::DTypeQ s_frag_f16[KTraits::NUM_MMA_Q][KTraits::NUM_MMA_KV][8];
1739:   if constexpr (std::is_same_v<typename KTraits::DTypeQKAccum, float>) {
1740: #pragma unroll
1741:     for (uint32_t mma_q = 0; mma_q < KTraits::NUM_MMA_Q; ++mma_q) {
1742: #pragma unroll
1743:       for (uint32_t mma_kv = 0; mma_kv < KTraits::NUM_MMA_KV; ++mma_kv) {
1744:         vec_cast<typename KTraits::DTypeQ, float>::cast<8>(s_frag_f16[mma_q][mma_kv],
1745:                                                            s_frag[mma_q][mma_kv]);
1746:       }
1747:     }
1748:   }
1749: 
1750:   if constexpr (KTraits::AttentionVariant::use_softmax) {
1751: #pragma unroll
1752:     for (uint32_t mma_q = 0; mma_q < KTraits::NUM_MMA_Q; ++mma_q) {
1753: #pragma unroll
1754:       for (uint32_t mma_kv = 0; mma_kv < KTraits::NUM_MMA_KV; ++mma_kv) {
1755:         if constexpr (std::is_same_v<typename KTraits::DTypeQKAccum, float>) {
1756:           mma::m16k16_rowsum_f16f16f32(d[mma_q], s_frag_f16[mma_q][mma_kv]);
1757:         } else {
1758:           mma::m16k16_rowsum_f16f16f32(d[mma_q], s_frag[mma_q][mma_kv]);
1759:         }
1760:       }
1761:     }
1762:   }
1763: 
1764: #pragma unroll
1765:   for (uint32_t mma_kv = 0; mma_kv < KTraits::NUM_MMA_KV; ++mma_kv) {
1766: #pragma unroll
1767:     for (uint32_t mma_d = 0; mma_d < KTraits::NUM_MMA_D_VO; ++mma_d) {
1768:       if (mma_d >= d_base && mma_d < d_base + KTraits::NUM_MMA_D_VO_TILE) {
1769:         uint32_t b_frag[4];
1770:         if constexpr (sizeof(typename KTraits::DTypeKV) == 1 && !REPACK_BF16) {
1771:           uint32_t b_frag_quant[2];
1772:           if (mma_d % 2 == 0) {
1773:             v_smem->ldmatrix_m8n8x4_trans_left_half(*v_smem_offset_r, b_frag_quant);
1774:           } else {
1775:             v_smem->ldmatrix_m8n8x4_trans_right_half(*v_smem_offset_r, b_frag_quant);
1776:           }
1777: 
1778:           if constexpr (is_fp4_type_v<typename KTraits::DTypeKV>) {
1779:             b_frag_quant[0] = frag_layout_swizzle_16b_to_4b_trans(b_frag_quant[0]);
1780:             b_frag_quant[1] = frag_layout_swizzle_16b_to_4b_trans(b_frag_quant[1]);
1781:           } else {
1782:             b_frag_quant[0] = frag_layout_swizzle_16b_to_8b_trans(b_frag_quant[0]);
1783:             b_frag_quant[1] = frag_layout_swizzle_16b_to_8b_trans(b_frag_quant[1]);
1784:           }
1785:           vec_cast<typename KTraits::DTypeQ, typename KTraits::DTypeKV>::cast<8>(
1786:               (typename KTraits::DTypeQ*)b_frag, (typename KTraits::DTypeKV*)b_frag_quant);
1787:           swap(b_frag[1], b_frag[2]);
1788:           if constexpr (is_fp4_type_v<typename KTraits::DTypeKV>) {
1789:             // Apply scaling factors for V.
1790:             // SF smem is linear: sf[kv_row * SF_COLS + hd_group], SF_COLS = HEAD_DIM_VO/16.
1791:             // For transposed B (V), thread t's KV rows are 2*(t%4)+{0,1} and 2*(t%4)+{8,9}
1792:             // in the mma_kv tile. After swap, b_frag[0,2] cover rows {r0, r0+1} and
1793:             // b_frag[1,3] cover rows {r0+8, r0+9}. Each half2 needs two distinct SFs.
1794:             using DTypeQ_ = typename KTraits::DTypeQ;
1795:             using packed2_ =
1796:                 std::conditional_t<std::is_same_v<DTypeQ_, half>, half2, __nv_bfloat162>;
1797:             constexpr uint32_t SF_COLS_V = KTraits::NUM_MMA_D_VO;  // HEAD_DIM_VO / 16
1798:             uint32_t sf_base = (mma_kv * 16 + 2 * (lane_idx % 4)) * SF_COLS_V + mma_d;
1799:             __nv_fp8_e4m3 sf0_fp8, sf1_fp8, sf2_fp8, sf3_fp8;
1800:             sf0_fp8.__x = v_sf_smem[sf_base];
1801:             sf1_fp8.__x = v_sf_smem[sf_base + SF_COLS_V];
1802:             sf2_fp8.__x = v_sf_smem[sf_base + 8 * SF_COLS_V];
1803:             sf3_fp8.__x = v_sf_smem[sf_base + 9 * SF_COLS_V];
1804:             packed2_ scale_lo{static_cast<DTypeQ_>(sf0_fp8), static_cast<DTypeQ_>(sf1_fp8)};
1805:             packed2_ scale_hi{static_cast<DTypeQ_>(sf2_fp8), static_cast<DTypeQ_>(sf3_fp8)};
1806:             *(packed2_*)&b_frag[0] = __hmul2(*(packed2_*)&b_frag[0], scale_lo);
1807:             *(packed2_*)&b_frag[1] = __hmul2(*(packed2_*)&b_frag[1], scale_hi);
1808:             *(packed2_*)&b_frag[2] = __hmul2(*(packed2_*)&b_frag[2], scale_lo);
1809:             *(packed2_*)&b_frag[3] = __hmul2(*(packed2_*)&b_frag[3], scale_hi);
1810:           }
1811:         } else {
1812:           v_smem->ldmatrix_m8n8x4_trans(*v_smem_offset_r, b_frag);
1813:         }
1814:         const uint32_t mma_d_local = mma_d - d_base;
1815: #pragma unroll
1816:         for (uint32_t mma_q = 0; mma_q < KTraits::NUM_MMA_Q; ++mma_q) {
1817:           if constexpr (std::is_same_v<typename KTraits::DTypeQKAccum, float>) {
1818:             mma::mma_sync_m16n16k16_row_col_f16f16f32<typename KTraits::DTypeQ>(
1819:                 o_frag[mma_q][mma_d_local], (uint32_t*)s_frag_f16[mma_q][mma_kv], b_frag);
1820:           } else {
1821:             mma::mma_sync_m16n16k16_row_col_f16f16f32<typename KTraits::DTypeQ>(
1822:                 o_frag[mma_q][mma_d_local], (uint32_t*)s_frag[mma_q][mma_kv], b_frag);
1823:           }
1824:         }
1825:       }
1826:       if constexpr (sizeof(typename KTraits::DTypeKV) == 1 && !REPACK_BF16) {
1827:         if (mma_d % 2 == 1) {
1828:           *v_smem_offset_r =
1829:               v_smem->template advance_offset_by_column<2>(*v_smem_offset_r, mma_d / 2);
1830:         }
1831:       } else {
1832:         *v_smem_offset_r = v_smem->template advance_offset_by_column<2>(*v_smem_offset_r, mma_d);
1833:       }
1834:     }
1835:     *v_smem_offset_r = v_smem->template advance_offset_by_row<16, VV_STRIDE>(*v_smem_offset_r) -
1836:                        VV_ESIZE * KTraits::NUM_MMA_D_VO;
1837:   }
1838:   *v_smem_offset_r -= 16 * KTraits::NUM_MMA_KV * VV_STRIDE;
1839: }

