218: template <typename fp8_dtype, typename fp16_dtype>
219: __device__ void fast_dequant_f8f16x4(uint32_t* input, uint2* output) {
220:   uint32_t q = *input;
221:   if constexpr (std::is_same_v<fp8_dtype, __nv_fp8_e5m2> && std::is_same_v<fp16_dtype, half>) {
222:     output->x = __byte_perm(0U, q, 0x5140);
223:     output->y = __byte_perm(0U, q, 0x7362);
224:   } else {
225:     constexpr int FP8_EXPONENT = get_exponent_bits<fp8_dtype>();
226:     constexpr int FP8_MANTISSA = get_mantissa_bits<fp8_dtype>();
227:     constexpr int FP16_EXPONENT = get_exponent_bits<fp16_dtype>();
228: 
229:     constexpr int RIGHT_SHIFT = FP16_EXPONENT - FP8_EXPONENT;
230:     // Calculate MASK for extracting mantissa and exponent
231:     constexpr int MASK1 = 0x80000000;
232:     constexpr int MASK2 = MASK1 >> (FP8_EXPONENT + FP8_MANTISSA);
233:     constexpr int MASK3 = MASK2 & 0x7fffffff;
234:     constexpr int MASK = MASK3 | (MASK3 >> 16);
235:     q = __byte_perm(q, q, 0x1302);
236: 
237:     // Extract and shift FP8 values to FP16 format
238:     uint32_t Out1 = (q & 0x80008000) | ((q & MASK) >> RIGHT_SHIFT);
239:     uint32_t Out2 = ((q << 8) & 0x80008000) | (((q << 8) & MASK) >> RIGHT_SHIFT);
240: 
241:     constexpr int BIAS_OFFSET = (1 << (FP16_EXPONENT - 1)) - (1 << (FP8_EXPONENT - 1));
242:     // Construct and apply exponent bias
243:     if constexpr (std::is_same_v<fp16_dtype, half>) {
244:       const half2 bias_reg = __float2half2_rn(float(1 << BIAS_OFFSET));
245: 
246:       // Convert to half2 and apply bias
247:       *(half2*)&(output->x) = __hmul2(*reinterpret_cast<const half2*>(&Out1), bias_reg);
255:       *(nv_bfloat162*)&(output->y) =
256:           __hmul2(*reinterpret_cast<const nv_bfloat162*>(&Out2), bias_reg);
257:     }
258:   }
259: }
