262: struct vec_cast<nv_bfloat16, __nv_fp8_e4m3> {
263:   template <size_t vec_size>
264:   FLASHINFER_INLINE static void cast(nv_bfloat16* dst, const __nv_fp8_e4m3* src) {
265:     if constexpr (vec_size == 1) {
266:       dst[0] = nv_bfloat16(src[0]);
267:     } else if constexpr (vec_size == 2) {
268:       dst[0] = nv_bfloat16(src[0]);
269:       dst[1] = nv_bfloat16(src[1]);
270:     } else {
271:       static_assert(vec_size % 4 == 0, "vec_size must be a multiple of 4");
272: #pragma unroll
273:       for (uint32_t i = 0; i < vec_size / 4; ++i) {
274:         fast_dequant_f8f16x4<__nv_fp8_e4m3, nv_bfloat16>((uint32_t*)&src[i * 4],
275:                                                          (uint2*)&dst[i * 4]);
276:       }
277:     }
278:   }
279: };
