510: __CUDA_HOSTDEVICE_FP8_DECL__ __half_raw
511: __nv_cvt_fp8_to_halfraw(const __nv_fp8_storage_t x,
512:                         const __nv_fp8_interpretation_t fp8_interpretation) {
513:     __half_raw res;
514:     res.x = 0U;
515: #if (defined __CUDA_ARCH__) && (__CUDA_ARCH__ >= 890)
516:     res.x =
517:         __nv_cvt_fp8x2_to_halfraw2((__nv_fp8x2_storage_t)x, fp8_interpretation)
518:             .x;
519: #else
520:     unsigned short int ur = (unsigned short int)x;
521:     ur = (unsigned short int)(ur << 8U);
522: 
523:     if (fp8_interpretation == __NV_E5M2) {
524:         if ((ur & 0x7FFFU) > 0x7C00U) {
525:             /* If NaN, return canonical NaN */
526:             ur = 0x7FFFU;
527:         }
528:     } else { // __NV_E4M3
529:         unsigned short int sign = ur & 0x8000U;
530:         unsigned short int exponent =
531:             (unsigned short int)(((ur & 0x7800U) >> 1U) + 0x2000U);
532:         unsigned short int mantissa = (ur & 0x0700U) >> 1U;
533:         unsigned char absx = 0x7FU & (unsigned char)x;
534: 
535:         if (absx == 0x7FU) // NaN
536:         {
537:             ur = 0x7FFFU; // fp16 canonical NaN, discard sign
538:         } else if (exponent == 0x2000U) {
539:             // zero or denormal
540:             if (mantissa != 0U) {
541:                 // normalize
542:                 mantissa = (unsigned short int)(mantissa << 1U);
543:                 while ((mantissa & 0x0400U) == 0U) {
544:                     mantissa = (unsigned short int)(mantissa << 1U);
545:                     exponent = (unsigned short int)(exponent - 0x0400U);
557:     }
558:     res.x = ur;
559: #endif
560:     return res;
561: }
