476:                                            const uint32_t stride_n, const uint32_t kv_idx_base,
477:                                            const uint32_t kv_len, const dim3 tid = threadIdx) {
478:   // NOTE: for fp8, this function doesn't work for head_dim = 64 at the moment
479:   using DTypeKV = typename KTraits::DTypeKV;
480:   constexpr bool IS_FP4 = is_fp4_type_v<DTypeKV>;
481:   constexpr uint32_t CTA_TILE_KV = KTraits::CTA_TILE_KV;
482:   constexpr uint32_t NUM_WARPS = KTraits::NUM_WARPS;
483:   constexpr uint32_t NUM_WARPS_Q = KTraits::NUM_WARPS_Q;
484:   constexpr bool PAD_K = !produce_v && KTraits::HYLE_FP8_SHORT_K;
485:   constexpr uint32_t NUM_MMA_D = PAD_K ? 8 : (produce_v ? KTraits::NUM_MMA_D_VO : KTraits::NUM_MMA_D_QK);
486:   constexpr uint32_t NUM_MMA_KV = KTraits::NUM_MMA_KV;
487:   constexpr uint32_t UPCAST_STRIDE =
488:       produce_v ? KTraits::UPCAST_STRIDE_V : KTraits::UPCAST_STRIDE_K;
489:   const uint32_t warp_idx = get_warp_idx<KTraits>(tid.y, tid.z), lane_idx = tid.x;
490: 
491:   if constexpr (KTraits::SWIZZLE_MODE_KV == SwizzleMode::k128B) {
492:     uint32_t kv_idx = kv_idx_base + warp_idx * 4 + lane_idx / 8;
493:     // NOTE: NUM_MMA_KV * 4 / NUM_WARPS_Q = NUM_WARPS_KV * NUM_MMA_KV * 4 / num_warps
494:     static_assert(NUM_MMA_KV * 4 % NUM_WARPS_Q == 0);
495: #pragma unroll
496:     for (uint32_t i = 0; i < NUM_MMA_KV * 4 / NUM_WARPS_Q; ++i) {
497: #pragma unroll
498:       for (uint32_t j = 0; j < NUM_MMA_D / (8 / sizeof(DTypeKV)); ++j) {
499:         // FP4 GMEM rows are packed 2x denser; load 64b (upper 64b of smem slot zeroed).
500:         if constexpr (IS_FP4) {
501:           smem.template load_64b_async<fill_mode>(*smem_offset, *gptr, kv_idx < kv_len);
502:         } else {
503:           if constexpr (PAD_K) {
504:             smem.template load_128b_async<SharedMemFillMode::kFillZero>(
505:                 *smem_offset, *gptr, kv_idx < kv_len && lane_idx % 8 < 4);
506:           } else {
507:             smem.template load_128b_async<fill_mode>(*smem_offset, *gptr, kv_idx < kv_len);
508:           }
509:         }
510:         *smem_offset = smem.template advance_offset_by_column<8>(*smem_offset, j);
511:         *gptr += (IS_FP4 ? 4 : 8) * upcast_size<DTypeKV>();
512:       }
513:       kv_idx += NUM_WARPS * 4;
514:       *smem_offset =
515:           smem.template advance_offset_by_row<NUM_WARPS * 4, UPCAST_STRIDE>(*smem_offset) -
516:           sizeof(DTypeKV) * NUM_MMA_D;
517:       *gptr += NUM_WARPS * 4 * stride_n -
518:                (IS_FP4 ? 4 : 8) * upcast_size<DTypeKV>() * (NUM_MMA_D / (8 / sizeof(DTypeKV)));
519:     }
520:     *smem_offset -= CTA_TILE_KV * UPCAST_STRIDE;
521:   } else {
522:     uint32_t kv_idx = kv_idx_base + warp_idx * 8 + lane_idx / 4;
523:     // NOTE: NUM_MMA_KV * 2 / NUM_WARPS_Q = NUM_WARPS_KV * NUM_MMA_KV * 2 / num_warps
524:     static_assert(NUM_MMA_KV * 2 % NUM_WARPS_Q == 0);
525: #pragma unroll
526:     for (uint32_t i = 0; i < NUM_MMA_KV * 2 / NUM_WARPS_Q; ++i) {
527:       // FP4 GMEM rows are packed 2x denser; load 64b (upper 64b of smem slot zeroed).
528:       if constexpr (IS_FP4) {
529:         smem.template load_64b_async<fill_mode>(*smem_offset, *gptr, kv_idx < kv_len);
530:       } else {
531:         smem.load_128b_async<fill_mode>(*smem_offset, *gptr, kv_idx < kv_len);
532:       }
533:       *smem_offset =
534:           smem.template advance_offset_by_row<NUM_WARPS * 8, UPCAST_STRIDE>(*smem_offset);
535:       kv_idx += NUM_WARPS * 8;
536:       *gptr += NUM_WARPS * 8 * stride_n;
537:     }
538:     *smem_offset -= KTraits::CTA_TILE_KV * UPCAST_STRIDE;
539:   }
