560:   constexpr bool PAD_K = !produce_v && KTraits::HYLE_FP8_SHORT_K;
561:   constexpr uint32_t NUM_MMA_D = PAD_K ? 8 : (produce_v ? KTraits::NUM_MMA_D_VO : KTraits::NUM_MMA_D_QK);
562:   constexpr uint32_t UPCAST_STRIDE =
563:       produce_v ? KTraits::UPCAST_STRIDE_V : KTraits::UPCAST_STRIDE_K;
564:   // FP4 stores 2 elements per byte in GMEM (packed); SMEM uses 64b data + 64b zero per 128b slot.
565:   // Use a 64b async load (cp.async with src-size=8) and advance GMEM pointer by half the normal
566:   // amount, while SMEM addressing remains unchanged.
567:   constexpr bool IS_FP4 = is_fp4_type_v<DType>;
568:   if constexpr (KTraits::SWIZZLE_MODE_KV == SwizzleMode::k128B) {
569:     uint32_t kv_idx = kv_idx_base + warp_idx * 4 + lane_idx / 8;
570:     // NOTE: NUM_MMA_KV * 4 / NUM_WARPS_Q = NUM_WARPS_KV * NUM_MMA_KV * 4 / num_warps
571:     static_assert(NUM_MMA_KV * 4 % NUM_WARPS_Q == 0);
572: #pragma unroll
573:     for (uint32_t i = 0; i < NUM_MMA_KV * 4 / NUM_WARPS_Q; ++i) {
574:       DType* gptr = kv_ptr + thr_local_kv_offset[i];
