583:                 *smem_offset, gptr, kv_idx < kv_len && lane_idx % 8 < 4);
584:           } else {
585:             smem.load_128b_async<fill_mode>(*smem_offset, gptr, kv_idx < kv_len);
586:           }
587:         }
588:         *smem_offset = smem.template advance_offset_by_column<8>(*smem_offset, j);
589:         // FP4: GMEM row is HEAD_DIM/2 bytes wide (packed), so advance by half
590:         gptr += (IS_FP4 ? 4 : 8) * upcast_size<DType>();
591:       }
592:       kv_idx += NUM_WARPS * 4;
593:       *smem_offset =
594:           smem.template advance_offset_by_row<NUM_WARPS * 4, UPCAST_STRIDE>(*smem_offset) -
595:           sizeof(DType) * NUM_MMA_D;
596:     }
597:     *smem_offset -= KTraits::CTA_TILE_KV * UPCAST_STRIDE;
598:   } else {
599:     uint32_t kv_idx = kv_idx_base + warp_idx * 8 + lane_idx / 4;
600:     // NOTE: NUM_MMA_KV * 2 / NUM_WARPS_Q = NUM_WARPS_KV * NUM_MMA_KV * 2 / num_warps
601:     static_assert(NUM_MMA_KV * 2 % NUM_WARPS_Q == 0);
602: #pragma unroll
603:     for (uint32_t i = 0; i < NUM_MMA_KV * 2 / NUM_WARPS_Q; ++i) {
604:       DType* gptr = kv_ptr + thr_local_kv_offset[i];
605:       if constexpr (IS_FP4) {
606:         smem.load_64b_async<fill_mode>(*smem_offset, gptr, kv_idx < kv_len);
607:       } else {
608:         smem.load_128b_async<fill_mode>(*smem_offset, gptr, kv_idx < kv_len);
609:       }
610:       kv_idx += NUM_WARPS * 8;
611:       *smem_offset =
612:           smem.template advance_offset_by_row<NUM_WARPS * 8, UPCAST_STRIDE>(*smem_offset);
613:     }
